# Prefix/Suffix/Root morphological heuristics for rich and natural Vietnamese meanings
SUFFIX_RULES = [
    ("tion", "sự ", "n."),
    ("sion", "sự ", "n."),
    ("ment", "sự ", "n."),
    ("ness", "tính ", "n."),
    ("ity", "tính ", "n."),
    ("able", "có thể ", "adj."),
    ("ible", "có thể ", "adj."),
    ("ful", "đầy ", "adj."),
    ("less", "không có ", "adj."),
    ("ous", "thuộc ", "adj."),
    ("ive", "có tính ", "adj."),
    ("al", "thuộc về ", "adj."),
    ("ic", "thuộc ", "adj."),
    ("ly", "một cách ", "adv."),
]

def guess_meaning(word, pos, sense=""):
    if sense:
        return sense
    for suffix, prefix_vn, _ in SUFFIX_RULES:
        if word.endswith(suffix):
            stem = word[:-len(suffix)]
            if stem in CORE_TRANSLATIONS:
                base_meaning = CORE_TRANSLATIONS[stem][0]
                return f"{prefix_vn}{base_meaning}"
    if pos.startswith("v"):
        return f"thực hiện hành động {word}"
    elif pos.startswith("adj"):
        return f"mang tính chất {word}"
    elif pos.startswith("adv"):
        return f"một cách {word}"
    return f"từ {word}"

def clean_word_entry(raw_word):
    cleaned = re.sub(r'\d+$', '', raw_word)
    sense = ""
    m = re.search(r'\((.*?)\)', cleaned)
    if m:
        sense = m.group(1).strip()
    clean_w = re.sub(r'\(.*?\)', '', cleaned).strip()
    return clean_w, sense

def parse_pdf():
    reader = PdfReader(PDF_PATH)
    full_text = ""
    for page in reader.pages:
        full_text += "\n" + page.extract_text()

    lines = [line.strip() for line in full_text.split('\n') if line.strip()]
    current_level = "B2"
    skip_phrases = ['Oxford University Press', 'The Oxford 5000', 'As well as the Oxford', '3000, it includes', 'which are listed here']
    
    entries = []
    seen = set()

    for line in lines:
        if line in ['B2', 'C1']:
            current_level = line
            continue
        if any(sp in line for sp in skip_phrases):
            continue
        m = re.match(r'^([a-zA-Z\s\-\'\/\d\(\)]+?)\s+(n\.|v\.|adj\.|adv\.|prep\.|conj\.|pron\.|det\.|num\.|number|exclam\.)(.*)$', line)
        if m:
            raw_w = m.group(1).strip()
            pos = (m.group(2) + m.group(3)).strip()
            word, sense = clean_word_entry(raw_w)
            
            key = f"{word}_{pos}"
            if key in seen:
                continue
            seen.add(key)

            low = word.lower()
            if low in CORE_TRANSLATIONS:
                vi, ipa, ex, exVi = CORE_TRANSLATIONS[low]
            else:
                ipa = f"/{word}/"
                vi = guess_meaning(word, pos, sense)
                ex = f"The word '{word}' is essential in advanced English."
                exVi = f"Từ '{word}' là từ thiết yếu trong tiếng Anh nâng cao."
            
            entries.append({
                "id": f"{current_level.lower()}-{len(entries)+1}",
                "word": word,
                "pos": pos,
                "ipa": ipa,
                "meaning": vi,
                "level": current_level,
                "example": ex,
                "exampleVi": exVi,
                "sense": sense
            })

    return entries

def main():
    pdf_entries = parse_pdf()
    print(f"Extracted {len(pdf_entries)} entries from Oxford PDF.")

    all_vocab = []

    # Import initial A1-B1 lists
    from generate_vocab import A1_WORDS, A2_WORDS, B1_WORDS
    for i, item in enumerate(A1_WORDS):
        all_vocab.append(item)
    for i, item in enumerate(A2_WORDS):
        all_vocab.append(item)
    for i, item in enumerate(B1_WORDS):
        all_vocab.append(item)
    
    all_vocab.extend(pdf_entries)

    os.makedirs(os.path.dirname(OUT_JSON), exist_ok=True)
    with open(OUT_JSON, "w", encoding="utf-8") as f:
        json.dump(all_vocab, f, ensure_ascii=False, indent=2)

    print(f"Total vocabulary dataset saved: {len(all_vocab)} words to {OUT_JSON}")

if __name__ == "__main__":
    main()
